  // ax ＋ b の 形
  const lin = (a, b, v = 'x') => { const A = a === 1 ? v : a === -1 ? `−${v}` : a === 0 ? '' : `${N(a)}${v}`; if (!b) return A || '0'; if (!A) return N(b); return `${A} ${b < 0 ? '−' : '＋'} ${Math.abs(b)}`; };
  const big = s => `<span class="big">${s}</span>`;
