  const qn = (text, ans, key, steps) => ({ key: key || text, text, boxes: ans.map(() => ''), answer: ans, steps });
  const ch = (stem, opts, correct, key, tate) => { const o = shuffle([...new Set(opts)]); return { key: (key || stem) + '#' + correct, text: `${stem}<br><span class="ch">${o.map((x, i) => `<b>${i + 1}</b> ${x}`).join(tate ? '<br>' : '　')}</span>`, boxes: [''], answer: [o.indexOf(correct) + 1] }; };
  const bank = (B, ask = '', tate = true) => () => { const b = pick(B); return ch(`${b[0]}${ask}`, b.slice(1), b[1], b[0], tate); };
  const ENTER = 'こたえを テンキーで いれて、Enterを おそう。', CHOOSE = 'こたえの {番号|ばんごう}を テンキーで いれよう。';
