  const TOPIC = [['通学時間', '分', 5, [0, 5, 10]], ['1日の 読書時間', '分', 10, [0, 10, 20]], ['ハンドボール投げの 記録', 'm', 4, [8, 12, 16]], ['垂直(すいちょく)とびの 記録', 'cm', 5, [30, 35, 40]], ['身長', 'cm', 5, [135, 140, 145]], ['反復横(はんぷくよこ)とびの 記録', '回', 4, [32, 36, 40]], ['1か月に 読んだ 本の 数', 'さつ', 2, [0, 2]]];
